import Image from "next/image";

type MainNavigationItemProps = {
    label: string;
    active?: boolean;
    lightBackground?: boolean;
};

const activeIndicatorDark =
    "https://www.figma.com/api/mcp/asset/d77e5cdd-e4f9-4c9e-872f-6a43db2aa49c.svg";

const activeIndicatorLight =
    "https://www.figma.com/api/mcp/asset/440575eb-a9ca-48b1-990d-31af80d3fa75.svg";

export default function MainNavigationItem({
    label,
    active = false,
    lightBackground = false,
    }: MainNavigationItemProps) {
    const indicator = lightBackground
        ? activeIndicatorLight
        : activeIndicatorDark;

    return (
        <div
        className={`flex flex-col items-center ${
            active ? "gap-[3px] pt-[5px]" : "gap-[4px]"
        }`}
        data-node-id="135:8922"
        >
        <div className="flex items-center gap-2 rounded-[12px] px-4 py-3">
            <span
            className={`text-[14px] leading-[1.25] text-white ${
                active ? "font-semibold" : "font-medium"
            }`}
            >
            {label}
            </span>
        </div>

        {active && (
            <div className="relative h-0 w-full">
            <Image
                src={indicator}
                alt=""
                fill
                sizes="100%"
                className="object-fill"
            />
            </div>
        )}
        </div>
    );
}